  <style>
    /* ===== CSS RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --red: #C41E3A;
      --red-dark: #a1182f;
      --red-light: #e8354f;
      --navy: #1B3A5C;
      --navy-dark: #132b45;
      --navy-light: #2a5080;
      --white: #FFFFFF;
      --gray-50: #F9F8F6;
