      --gray-200: #E5E2DC;
      --gray-300: #D1CCC4;
      --gray-400: #A8A19A;
      --gray-500: #7A746D;
      --gray-600: #5C5650;
      --gray-700: #3D3835;
      --gray-800: #2A2522;
      --gray-900: #1A1614;
      --font-display: 'Space Grotesk', system-ui, sans-serif;
      --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
      --shadow-sm: 0 1px 2px rgba(26,22,20,0.05);
      --shadow-md: 0 4px 12px rgba(26,22,20,0.08);
      --shadow-lg: 0 12px 32px rgba(26,22,20,0.12);
      --shadow-xl: 0 24px 48px rgba(26,22,20,0.16);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
      --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
      --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

    body {
      font-family: var(--font-body);
      color: var(--gray-700);
      background: var(--white);
      line-height: 1.65;
      font-size: 16px;
      overflow-x: hidden;
    }

    h1, h2, h3, h4 { font-family: var(--font-display); color: var(--gray-900); line-height: 1.15; }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    ul { list-style: none; }

    /* ===== UTILITY ===== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

    /* ===== GRAIN TEXTURE ===== */
    body::before {
      content: '';
      position: fixed;
      inset: 0;
      pointer-events: none;
      z-index: 9999;
      opacity: 0.025;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: var(--transition-base);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .header-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-display);
      font-weight: 700;
      font-size: 18px;
      color: var(--navy);
      white-space: nowrap;
    }
    .header-logo .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--red);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 18px;
      font-weight: 700;
    }

    .header-nav { display: flex; align-items: center; gap: 28px; }
    .header-nav a {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color var(--transition-fast);
      position: relative;
    }
    .header-nav a:hover { color: var(--navy); }
    .header-nav a::after {
      content: '';
