    .btn-ghost:hover { background: var(--navy); color: white; }
    .btn-lg { padding: 14px 32px; font-size: 16px; border-radius: var(--radius-md); }
    .btn:focus-visible { outline: 3px solid rgba(196,30,58,0.5); outline-offset: 2px; }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      cursor: pointer;
      z-index: 1001;
