      text-align: center;
    }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 92vh;
      display: flex;
      align-items: center;
      overflow: hidden;
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 40%, #243f5f 100%);
      padding-top: 72px;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse at 20% 50%, rgba(196,30,58,0.15) 0%, transparent 60%),
        radial-gradient(ellipse at 80% 20%, rgba(43,80,128,0.3) 0%, transparent 50%);
      z-index: 1;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 200px;
      background: linear-gradient(to top, var(--white), transparent);
      z-index: 2;
    }
    .hero-pattern {
      position: absolute;
      inset: 0;
      opacity: 0.04;
      background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      z-index: 0;
    }

    .hero-content {
      position: relative;
      z-index: 3;
      max-width: 680px;
      padding: 80px 0 120px;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 16px;
      background: rgba(196,30,58,0.2);
      border: 1px solid rgba(196,30,58,0.3);
      border-radius: 100px;
      color: rgba(255,255,255,0.9);
      font-size: 13px;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      margin-bottom: 28px;
      animation: fadeSlideDown 0.8s ease-out both;
    }
    .hero-badge .pulse-dot {
      width: 8px;
      height: 8px;
      background: var(--red-light);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(1.3); }
    }

    .hero-title {
      font-size: clamp(40px, 6vw, 72px);
      font-weight: 700;
      color: white;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
      animation: fadeSlideDown 0.8s ease-out 0.15s both;
    }
    .hero-title .accent { color: var(--red-light); }

    .hero-subtitle {
      font-size: clamp(16px, 2vw, 19px);
      color: rgba(255,255,255,0.75);
      line-height: 1.7;
      margin-bottom: 40px;
      max-width: 540px;
      animation: fadeSlideDown 0.8s ease-out 0.3s both;
    }

    .hero-actions {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
      animation: fadeSlideDown 0.8s ease-out 0.45s both;
    }
    .hero-actions .btn-primary { box-shadow: 0 4px 20px rgba(196,30,58,0.4); font-size: 16px; padding: 14px 36px; }
    .hero-actions .btn-secondary { border-color: rgba(255,255,255,0.3); color: white; }
    .hero-actions .btn-secondary:hover { border-color: white; background: rgba(255,255,255,0.1); }

    .hero-image-area {
      position: absolute;
      right: 0;
      top: 72px;
      bottom: 0;
      width: 45%;
      z-index: 2;
      overflow: hidden;
    }
    .hero-image-area img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.35;
    }

    @keyframes fadeSlideDown {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    /* ===== MISSION ===== */
    .mission {
      padding: 100px 0 80px;
      position: relative;
    }
    .mission-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .mission-label {
      display: inline-block;
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--red);
      margin-bottom: 16px;
    }
    .mission-title {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
      line-height: 1.2;
    }
    .mission-text {
      font-size: 17px;
      line-height: 1.75;
      color: var(--gray-600);
    }
    .mission-text strong { color: var(--gray-800); }
    .mission-visual {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
    }
    .mission-visual .placeholder-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0;
