    .involved-header h2 {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 700;
      letter-spacing: -0.02em;
    }
    .involved-header p {
      max-width: 540px;
      margin: 16px auto 0;
      color: var(--gray-500);
      font-size: 17px;
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }
    .involved-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 40px 32px;
      transition: var(--transition-base);
      position: relative;
      overflow: hidden;
    }
    .involved-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: var(--navy);
      transition: height var(--transition-base);
    }
    .involved-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
    .involved-card:hover::before { height: 4px; }

    .involved-card .card-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--navy), var(--navy-light));
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      margin-bottom: 24px;
    }
    .involved-card h3 {
      font-size: 22px;
      font-weight: 700;
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }
    .involved-card p {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.65;
      margin-bottom: 24px;
    }
    .involved-card .card-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 14px;
      font-weight: 600;
      color: var(--navy);
      transition: gap var(--transition-fast), color var(--transition-fast);
    }
    .involved-card:hover .card-cta { color: var(--red); gap: 12px; }

    /* ===== NEWS ===== */
    .news {
      padding: 100px 0;
    }
    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 48px;
    }
    .news-header .label {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--red);
      margin-bottom: 12px;
    }
    .news-header h2 {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 700;
      letter-spacing: -0.02em;
    }
    .carousel-controls {
      display: flex;
      gap: 8px;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border: 1px solid var(--gray-300);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-500);
      transition: all var(--transition-fast);
      background: var(--white);
    }
    .carousel-btn:hover { border-color: var(--navy); color: var(--navy); background: var(--gray-50); }
    .carousel-btn:focus-visible { outline: 3px solid rgba(196,30,58,0.5); outline-offset: 2px; }

    .news-carousel-wrapper {
      overflow: hidden;
      margin: 0 -24px;
      padding: 0 24px;
    }
    .news-track {
      display: flex;
      gap: 28px;
      transition: transform var(--transition-slow);
    }
    .news-card {
      flex: 0 0 calc(50% - 14px);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: var(--transition-base);
    }
    .news-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

    .news-card-image {
      height: 200px;
      background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 40px;
    }
    .news-card-image .image-label {
      position: absolute;
      bottom: 12px;
      left: 12px;
      background: var(--red);
      color: white;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      padding: 4px 10px;
      border-radius: 4px;
    }

    .news-card-body { padding: 24px; }
    .news-card-body h3 {
      font-size: 19px;
      font-weight: 700;
      margin-bottom: 10px;
      letter-spacing: -0.01em;
      line-height: 1.3;
    }
    .news-card-body p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ===== DONATE CTA ===== */
    .donate-cta {
      padding: 100px 0;
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 50%, #2a4f70 100%);
      position: relative;
      overflow: hidden;
    }
    .donate-cta::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 30% 50%, rgba(196,30,58,0.12) 0%, transparent 60%);
    }
    .donate-cta .container { position: relative; z-index: 1; }

    .donate-cta-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .donate-cta .label {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: rgba(255,255,255,0.6);
      margin-bottom: 16px;
    }
    .donate-cta h2 {
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 700;
      color: white;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
      line-height: 1.15;
    }
    .donate-cta .cta-text {
      font-size: 17px;
      color: rgba(255,255,255,0.7);
      line-height: 1.7;
      margin-bottom: 32px;
    }
    .donate-cta .efficiency-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 16px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 100px;
      color: rgba(255,255,255,0.85);
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 32px;
    }
    .efficiency-badge .check-icon { color: #4ade80; }

    .impact-table {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      padding: 32px;
      backdrop-filter: blur(8px);
    }
    .impact-table h3 {
      color: white;
      font-size: 20px;
      margin-bottom: 24px;
      font-weight: 700;
    }
    .impact-row {
      display: flex;
      align-items: flex-start;
      gap: 16px;
      padding: 16px 0;
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .impact-row:last-child { border-bottom: none; }
    .impact-amount {
      font-family: var(--font-display);
      font-size: 20px;
      font-weight: 700;
      color: var(--red-light);
      min-width: 72px;
      flex-shrink: 0;
    }
    .impact-desc {
      font-size: 14px;
      color: rgba(255,255,255,0.7);
      line-height: 1.6;
    }
    .impact-table .btn-primary {
      width: 100%;
      margin-top: 24px;
      padding: 16px;
      font-size: 16px;
      border-radius: var(--radius-md);
    }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--gray-900);
      color: var(--gray-400);
      padding: 80px 0 40px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 56px;
    }
    .footer-brand .footer-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-display);
      font-weight: 700;
      font-size: 18px;
      color: white;
      margin-bottom: 16px;
    }
    .footer-brand .footer-logo .logo-icon {
      width: 32px;
      height: 32px;
      background: var(--red);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 15px;
      font-weight: 700;
    }
    .footer-brand p {
      font-size: 14px;
      line-height: 1.7;
      max-width: 280px;
    }
    .footer-col h4 {
      color: white;
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 20px;
    }
    .footer-col a {
      display: block;
      font-size: 14px;
      color: var(--gray-400);
      padding: 5px 0;
      transition: color var(--transition-fast);
    }
    .footer-col a:hover { color: white; }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.08);
      padding-top: 32px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }
    .footer-bottom p { font-size: 13px; }
    .footer-social {
      display: flex;
      gap: 16px;
    }
    .footer-social a {
      width: 36px;
      height: 36px;
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 14px;
      transition: all var(--transition-fast);
    }
    .footer-social a:hover { border-color: var(--red); color: var(--red); background: rgba(196,30,58,0.1); }

    /* ===== DONATE MODAL ===== */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(26,22,20,0.6);
      backdrop-filter: blur(4px);
      z-index: 2000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-base);
    }
    .modal-overlay.open { opacity: 1; visibility: visible; }

    .modal {
      background: var(--white);
      border-radius: var(--radius-xl);
      max-width: 520px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      transform: translateY(20px) scale(0.97);
      transition: transform var(--transition-base);
      box-shadow: var(--shadow-xl);
    }
    .modal-overlay.open .modal { transform: translateY(0) scale(1); }

    .modal-header {
      padding: 28px 32px 0;
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
    }
    .modal-header h2 {
      font-size: 24px;
      font-weight: 700;
      letter-spacing: -0.02em;
    }
    .modal-close {
      width: 36px;
      height: 36px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      transition: all var(--transition-fast);
      flex-shrink: 0;
    }
    .modal-close:hover { background: var(--gray-100); color: var(--gray-700); }

    .modal-body { padding: 24px 32px 32px; }
    .modal-body .modal-subtitle {
      font-size: 15px;
      color: var(--gray-500);
      margin-bottom: 24px;
      line-height: 1.6;
    }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 16px;
    }
    .amount-btn {
      padding: 14px 8px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 700;
      color: var(--gray-700);
      text-align: center;
      transition: all var(--transition-fast);
      background: var(--white);
    }
    .amount-btn:hover { border-color: var(--navy); color: var(--navy); }
    .amount-btn.selected { border-color: var(--red); background: rgba(196,30,58,0.05); color: var(--red); }
    .amount-btn .amount-label {
      display: block;
      font-size: 11px;
      font-weight: 500;
      color: var(--gray-400);
      margin-top: 2px;
      font-family: var(--font-body);
    }

    .custom-amount {
      margin-bottom: 24px;
    }
    .custom-amount input {
      width: 100%;
      padding: 14px 16px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-size: 16px;
      font-family: var(--font-display);
      font-weight: 600;
      color: var(--gray-800);
      outline: none;
      transition: border-color var(--transition-fast);
    }
    .custom-amount input:focus { border-color: var(--navy); }
    .custom-amount input::placeholder { color: var(--gray-300); font-weight: 400; }

    .frequency-toggle {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }
    .freq-btn {
      flex: 1;
      padding: 10px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      text-align: center;
      transition: all var(--transition-fast);
      background: var(--white);
      color: var(--gray-600);
    }
    .freq-btn:hover { border-color: var(--navy); }
    .freq-btn.selected { border-color: var(--navy); background: var(--navy); color: white; }

    .modal-donate-btn {
      width: 100%;
      padding: 16px;
      font-size: 16px;
      font-weight: 700;
      border-radius: var(--radius-md);
      background: var(--red);
      color: white;
      box-shadow: 0 4px 16px rgba(196,30,58,0.3);
      transition: all var(--transition-fast);
    }
    .modal-donate-btn:hover { background: var(--red-dark); box-shadow: 0 6px 24px rgba(196,30,58,0.4); transform: translateY(-1px); }

    .modal-secure {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      margin-top: 16px;
      font-size: 12px;
      color: var(--gray-400);
    }

    /* ===== SECTION REVEAL ANIMATION ===== */
    .reveal {
      opacity: 0;
      transform: translateY(30px);
      transition: opacity 0.7s ease-out, transform 0.7s ease-out;
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1200px) {
      .hero-image-area { width: 40%; }
      .footer-grid { grid-template-columns: 2fr 1fr 1fr 1fr; }
    }

    @media (max-width: 1024px) {
      .header-nav { display: none; }
      .utility-links { display: none; }
      .hamburger { display: flex; }
      .mobile-drawer { display: block; }

      .hero-image-area { display: none; }
      .hero-content { max-width: 100%; padding: 60px 0 100px; }

      .mission-inner { grid-template-columns: 1fr; gap: 40px; }
      .mission-visual { max-width: 500px; }

      .stats-grid { grid-template-columns: repeat(2, 1fr); }

      .involved-grid { grid-template-columns: 1fr; max-width: 500px; margin: 0 auto; }

      .donate-cta-inner { grid-template-columns: 1fr; gap: 48px; }

      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 768px) {
      .hero { min-height: 80vh; }
      .hero-title { font-size: 36px; }
      .hero-subtitle { font-size: 16px; }

      .stats-grid { grid-template-columns: 1fr 1fr; gap: 16px; }
      .stat-card { padding: 28px 20px; }
      .stat-number { font-size: 36px; }

      .news-card { flex: 0 0 100%; }

      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-bottom { flex-direction: column; text-align: center; }

      .amount-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .stats-grid { grid-template-columns: 1fr; }
      .hero-actions { flex-direction: column; }
      .hero-actions .btn { width: 100%; }
      .amount-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-brand { grid-column: auto; }
    }
  </style>
</head>
<body>

  <!-- ===== HEADER ===== -->
  <header class="header" id="header">
    <div class="container header-inner">
      <a href="#" class="header-logo" aria-label="Global Aid Alliance Home">
        <span class="logo-icon">G</span>
        Global Aid Alliance
      </a>

      <nav class="header-nav" aria-label="Main navigation">
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Programs &amp; Services</a>
        <a href="#involved">Volunteer</a>
        <a href="#" onclick="event.preventDefault()">Find Local Chapter</a>
      </nav>

      <div class="header-right">
        <div class="utility-links">
          <a href="#">Sign In</a>
          <span class="divider"></span>
          <a href="#">Contact Us</a>
          <span class="divider"></span>
          <a href="#">Espa&ntilde;ol</a>
        </div>
        <button class="btn btn-primary donate-trigger" aria-label="Donate Now">Donate</button>
        <button class="hamburger" id="hamburger" aria-label="Toggle menu" aria-expanded="false">
          <span></span><span></span><span></span>
        </button>
      </div>
    </div>

    <!-- Mobile drawer -->
    <div class="mobile-drawer" id="mobileDrawer" aria-hidden="true">
      <a href="#mission">About Us</a>
      <a href="#programs">Disaster Relief</a>
      <a href="#programs">Programs &amp; Services</a>
      <a href="#involved">Volunteer</a>
      <a href="#">Find Local Chapter</a>
      <a href="#">Sign In</a>
      <a href="#">Contact Us</a>
      <a href="#">Espa&ntilde;ol</a>
      <button class="btn btn-primary btn-lg mobile-donate-btn donate-trigger">Donate Now</button>
    </div>
  </header>

  <!-- ===== HERO ===== -->
  <section class="hero" id="hero">
    <div class="hero-pattern"></div>
    <div class="hero-image-area">
      <img src="https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?w=800&q=60" alt="Relief workers providing aid to a community" loading="eager">
    </div>
    <div class="container">
      <div class="hero-content">
        <div class="hero-badge">
          <span class="pulse-dot"></span>
          Active disaster response underway
        </div>
        <h1 class="hero-title">When Disaster Strikes,<br>We're <span class="accent">There</span></h1>
        <p class="hero-subtitle">From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
        <div class="hero-actions">
          <button class="btn btn-primary btn-lg donate-trigger">Donate Now</button>
          <a href="#involved" class="btn btn-secondary btn-lg">Become a Volunteer</a>
        </div>
      </div>
    </div>
  </section>

  <!-- ===== MISSION ===== -->
  <section class="mission" id="mission">
    <div class="container">
      <div class="mission-inner reveal">
        <div class="mission-content">
          <span class="mission-label">Our Mission</span>
          <h2 class="mission-title">Preventing &amp; alleviating human suffering in the face of emergencies</h2>
          <p class="mission-text">
            Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of <strong>donors</strong>.
          </p>
          <br>
          <p class="mission-text">
            We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most — regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities <strong>every step of the way</strong>.
          </p>
        </div>
        <div class="mission-visual">
          <img class="placeholder-img" src="https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?w=600&q=60" alt="Volunteers distributing supplies in a disaster-affected area">
          <span class="quote-mark">&ldquo;</span>
          <div class="overlay-text">
            <span class="big-number">77+</span>
            <span class="big-label">Years of humanitarian service</span>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ===== IMPACT STATS ===== -->
  <section class="impact" id="impact">
    <div class="container">
      <div class="impact-header reveal">
        <div class="label">Our Impact</div>
        <h2>Real Lives Changed</h2>
        <p>These figures represent families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.</p>
      </div>
      <div class="stats-grid reveal">
        <div class="stat-card">
          <div class="stat-icon">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
          </div>
          <div class="stat-number" data-target="12" data-suffix="M">0</div>
          <div class="stat-unit">People Assisted</div>
          <div class="stat-label">People assisted annually across our global network</div>
        </div>
        <div class="stat-card">
          <div class="stat-icon">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
          </div>
          <div class="stat-number" data-target="50" data-suffix=",000">0</div>
          <div class="stat-unit">Active Volunteers</div>
          <div class="stat-label">Volunteers active across our network worldwide</div>
        </div>
        <div class="stat-card">
          <div class="stat-icon">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>
          </div>
          <div class="stat-number" data-target="190">0</div>
          <div class="stat-unit">Countries</div>
          <div class="stat-label">Countries where we've provided humanitarian aid</div>
        </div>
